  // Azure OpenAI — same as upstream OpenAI pricing
  "gpt-4o (azure)": [2.5, 10],
  // Gemini
  "gemini-2.0-flash": [0.1, 0.4],
  "gemini-1.5-pro": [3.5, 10.5],
  "gemini-1.5-flash": [0.075, 0.3],
  // Bedrock (Claude via Bedrock)
  "anthropic.claude-sonnet-4-5-20251001-v1:0": [3, 15],
