import pc3 from "picocolors";
var SPINNER_FRAMES = ["\u280B", "\u2819", "\u2839", "\u2838", "\u283C", "\u2834", "\u2826", "\u2827", "\u2807", "\u280F"];
var INTERVAL_MS = 80;
var Spinner = class {
  text;
  frameIndex = 0;
  interval = null;
  isTTY;
  constructor(text) {
    this.text = text;
    this.isTTY = process.stderr.isTTY === true;
  }
  start() {
    if (this.isTTY) {
      this.interval = setInterval(() => {
        const frame = SPINNER_FRAMES[this.frameIndex % SPINNER_FRAMES.length];
        this.frameIndex++;
        process.stderr.write(`\r${frame} ${this.text}`);
      }, INTERVAL_MS);
    } else {
      process.stderr.write(`${this.text}...
`);
    }
    return this;
  }
  update(text) {
    this.text = text;
    if (!this.isTTY) {
      process.stderr.write(`${text}...
`);
    }
    return this;
  }
  succeed(text) {
    this.stop();
    const msg = text ?? this.text;
    if (this.isTTY) {
      process.stderr.write(`\r${pc3.green("\u2713")} ${msg}
`);
    } else {
      process.stderr.write(`\u2713 ${msg}
`);
    }
    return this;
  }
  fail(text) {
    this.stop();
    const msg = text ?? this.text;
    if (this.isTTY) {
      process.stderr.write(`\r${pc3.red("\u2717")} ${msg}
`);
    } else {
      process.stderr.write(`\u2717 ${msg}
`);
    }
    return this;
  }
  stop() {
    if (this.interval !== null) {
      clearInterval(this.interval);
      this.interval = null;
      if (this.isTTY) {
        process.stderr.write("\r\x1B[K");
      }
    }
    return this;
  }
};

// src/ui/table.ts
function renderTable(headers, rows) {
  const allRows = [headers, ...rows];
  const colWidths = headers.map((h, i) => {
    const maxRowWidth = rows.reduce((max, row) => Math.max(max, (row[i] ?? "").length), 0);
    return Math.max(h.length, maxRowWidth);
  });
  function formatRow(cells) {
    const padded = colWidths.map((w, i) => (cells[i] ?? "").padEnd(w));
    return `\u2502 ${padded.join(" \u2502 ")} \u2502`;
  }
  function formatSeparator(left, mid, right) {
    const parts = colWidths.map((w) => "\u2500".repeat(w + 2));
    return left + parts.join(mid) + right;
  }
  const lines = [];
  lines.push(formatSeparator("\u250C", "\u252C", "\u2510"));
  lines.push(formatRow(headers));
  lines.push(formatSeparator("\u251C", "\u253C", "\u2524"));
  for (const row of rows) {
    lines.push(formatRow(row));
  }
  lines.push(formatSeparator("\u2514", "\u2534", "\u2518"));
  return lines.join("\n");
}

